<?php
// Database Configuration
// This file is generated by install.php or can be configured manually.

$db_host = '%%DB_HOST%%';         // Database Server (e.g. localhost)
$db_user = '%%DB_USER%%';         // Database Username
$db_pass = '%%DB_PASS%%';         // Database Password
$db_name = '%%DB_NAME%%';         // Database Name

// Attempt to connect to MySQL database
$conn = mysqli_connect($db_host, $db_user, $db_pass, $db_name);

// Check connection
if (!$conn) {
    error_log('Database connection error: ' . mysqli_connect_error());
    die('Database connection error. Please verify your configuration in config.php.');
}

// Set character set to utf8mb4
mysqli_set_charset($conn, 'utf8mb4');
